public function set($name, $value = null)
{
    $properties = \is_array($name) ? $name : [$name => $value];

    foreach ($properties as $key => $value) {
        switch (Carbon::singularUnit(rtrim($key, 'z'))) {
            case 'year':
                $this->y = $value;

                break;

            case 'month':
                $this->m = $value;

                break;

            case 'week':
