                $this->d = $value;

                break;

            case 'daysexcludeweek':
            case 'dayzexcludeweek':
                $this->d = $this->weeks * (int) static::getDaysPerWeek() + $value;

                break;

            case 'hour':
                $this->h = $value;

                break;

            case 'minute':
                $this->i = $value;

                break;

            case 'second':
                $this->s = $value;

